insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_determination','determination','noun','the strong will to keep trying to achieve something difficult without giving up','[{"senseId":"determination_1","meaning":"the strong will to keep trying to achieve something difficult without giving up","acceptedParaphrases":["strong will","perseverance"],"masteryContexts":[{"contextId":"u2_41_determination_meaning","text":"With great determination, she trained every morning before school.","meaning":"a strong will not to give up","wrongMeanings":["a quick wish to finish early","a nervous fear of failing","a polite request for more time"]},{"contextId":"u2_41_determination_paraphrase","text":"His determination to succeed impressed the coach.","meaning":"firm decision to achieve something despite difficulty","wrongMeanings":["a quiet hope of being chosen","a sudden stroke of luck in a match","a careful plan for winning a prize"]}],"situationDistractors":["He gave up the climb after twenty minutes because it was tiring.","She stopped practising the piano as soon as the piece became difficult.","The team left the pitch at half time and never returned.","The team won the match easily because its opponents had only ten players.","The student copied the answers from a friend and handed in the work early.","The coach changed her mind about the plan and chose a different team."],"gapDistractors":[{"contextId":"u2_41_determination_gap_1","answer":"determination","wrong":["doubt","weakness","boredom"]},{"contextId":"u2_41_determination_gap_2","answer":"determination","wrong":["laziness","weakness","doubt"]},{"contextId":"u2_41_determination_gap_3","answer":"determination","wrong":["weakness","fear","laziness"]}],"spellingErrors":["determnation","detirmination","determinasion","deturmination","determinattion","determenation"],"masteryPassages":[{"passageId":"u2_41_determination_passage_1","contextId":"u2_41_determination_gap_1","text":"Jo failed her driving test three times, but she never gave up. Her ____ to pass finally paid off when she collected her licence on the fourth try.","answer":"determination"},{"passageId":"u2_41_determination_passage_2","contextId":"u2_41_determination_gap_2","text":"The mountain was steep, the weather was freezing and the climbers were exhausted. Only their ____ kept them walking towards the summit.","answer":"determination"}],"contextDependentParaphrases":[],"wrongParaphrases":["good luck","deep fear","sudden anger"],"misleadingDistractors":["a feeling of nervousness","permission to continue","a talent for something"]}]'::jsonb,'[]'::jsonb,'["sheer determination","great determination","show determination"]'::jsonb,'live'),
('vocab_overcome','overcome','verb','to succeed in dealing with a problem or difficulty that is stopping you','[{"senseId":"overcome_1","meaning":"to succeed in dealing with a problem or difficulty that is stopping you","acceptedParaphrases":["conquer","get past"],"masteryContexts":[{"contextId":"u2_42_overcome_meaning","text":"Many athletes overcome serious injuries to return to competition.","meaning":"succeed in dealing with a difficulty","wrongMeanings":["avoid facing a danger","cause a serious problem","wait for a problem to end"]},{"contextId":"u2_42_overcome_paraphrase","text":"It took years to overcome the language barrier.","meaning":"get past a problem that stops progress","wrongMeanings":["stay behind because of a problem","explain a problem to others","create a problem that stops progress"]}],"situationDistractors":["He gave up learning the guitar when his fingers began to hurt.","She avoided speaking in class because she was shy.","The team withdrew from the competition after the first defeat.","The runner avoided the steep hill by taking a longer road around it.","The old bridge was closed, so the bus used a different route.","The student never had any problem with the course and finished it early."],"gapDistractors":[{"contextId":"u2_42_overcome_gap_1","answer":"overcome","wrong":["increase","deepen","worsen"]},{"contextId":"u2_42_overcome_gap_2","answer":"overcome","wrong":["cause","create","increase"]},{"contextId":"u2_42_overcome_gap_3","answer":"overcome","wrong":["create","invent","admire"]}],"spellingErrors":["overcom","ovarcome","overcomme","overkome","over come","overcum"],"masteryPassages":[{"passageId":"u2_42_overcome_passage_1","contextId":"u2_42_overcome_gap_1","text":"When Sam moved to England, he could barely speak English. Within two years, he managed to ____ the language barrier and passed his exams.","answer":"overcome"},{"passageId":"u2_42_overcome_passage_2","contextId":"u2_42_overcome_gap_2","text":"Many successful people had a difficult start in life. They show that it is possible to ____ almost any obstacle with hard work and support.","answer":"overcome"}],"contextDependentParaphrases":[],"wrongParaphrases":["avoid","delay","cause"],"misleadingDistractors":["create a problem","avoid thinking about","give in to"]}]'::jsonb,'[]'::jsonb,'["overcome difficulties","overcome obstacles","overcome fear"]'::jsonb,'live'),
('vocab_accessory','accessory','noun','an extra item that is added to something or goes with it, such as a phone case or a scarf','[{"senseId":"accessory_1","meaning":"an extra item that is added to something or goes with it, such as a phone case or a scarf","acceptedParaphrases":["add-on","extra item"],"masteryContexts":[{"contextId":"u2_43_accessory_meaning","text":"Headphones are a popular accessory for smartphone users.","meaning":"an extra item that goes with something","wrongMeanings":["a main part that holds something up","a spare part kept in case of damage","a cheap copy of the real thing"]},{"contextId":"u2_43_accessory_paraphrase","text":"She wore a red scarf as her only accessory.","meaning":"an extra item that goes with clothes","wrongMeanings":["a piece of clothing worn underneath","a cheap material used for coats","a shop where clothes are sold"]}],"situationDistractors":["The factory built the main engine of the car by hand.","The shop repaired the broken screen of the phone.","The customer asked for a refund on the whole tablet.","The phone is made of glass and metal, and it has a large screen.","The shop sells coats, shoes and hats in many sizes.","The laptop is the main tool she uses for her studies."],"gapDistractors":[{"contextId":"u2_43_accessory_gap_1","answer":"accessory","wrong":["necessity","requirement","component"]},{"contextId":"u2_43_accessory_gap_2","answer":"accessory","wrong":["necessity","requirement","disaster"]},{"contextId":"u2_43_accessory_gap_3","answer":"accessory","wrong":["model","brand","version"]}],"spellingErrors":["accesory","acessory","accessary","accesorry","acsessory","axessory"],"masteryPassages":[{"passageId":"u2_43_accessory_passage_1","contextId":"u2_43_accessory_gap_1","text":"The basic phone costs very little, but customers often spend more on extras. A case or a charger is the most popular ____ in the shop.","answer":"accessory"},{"passageId":"u2_43_accessory_passage_2","contextId":"u2_43_accessory_gap_2","text":"Her outfit was plain and dark. A bright yellow scarf was the only ____ she wore, but it made everyone look twice.","answer":"accessory"}],"contextDependentParaphrases":[],"wrongParaphrases":["main part","warning sign","free gift"],"misleadingDistractors":["the main part of a machine","a spare part that has broken","a manual explaining how to use it"]}]'::jsonb,'[]'::jsonb,'["phone accessory","fashion accessory","computer accessory"]'::jsonb,'live'),
('vocab_equipment','equipment','noun','the tools, machines or clothing needed for a particular job or activity','[{"senseId":"equipment_1","meaning":"the tools, machines or clothing needed for a particular job or activity","acceptedParaphrases":["gear","apparatus"],"masteryContexts":[{"contextId":"u2_44_equipment_meaning","text":"Firefighters carry heavy equipment into burning buildings.","meaning":"tools and machines needed for a job","wrongMeanings":["workers who are trained for a job","money that is paid for a job","rules that are made for a job"]},{"contextId":"u2_44_equipment_paraphrase","text":"The gym has a lot of modern equipment.","meaning":"machines and tools for an activity","wrongMeanings":["rooms and spaces for an activity","people and teams for an activity","prices and fees for an activity"]}],"situationDistractors":["The coach explained the rules before the match began.","The cleaner locked the storage room at six o’clock.","A technician repaired the broken lift in the hotel.","The coach shouted instructions to the players from the side of the pitch.","The fans queued for hours to buy tickets for the final.","The club pays a small fee to use the hall on Thursday evenings."],"gapDistractors":[{"contextId":"u2_44_equipment_gap_1","answer":"equipment","wrong":["advice","information","permission"]},{"contextId":"u2_44_equipment_gap_2","answer":"equipment","wrong":["advice","information","permission"]},{"contextId":"u2_44_equipment_gap_3","answer":"equipment","wrong":["homework","luck","courage"]}],"spellingErrors":["equipement","equipmant","ekwipment","equiptment","equipmet","equipmment"],"wordFamilyForms":[{"form":"equipment","partOfSpeech":"noun","example":"The school has spent a lot of money on new sports equipment.","pedagogicallyUseful":true},{"form":"equip","partOfSpeech":"verb","example":"The college will equip every classroom with a projector.","pedagogicallyUseful":true,"altExample":"The hospital plans to equip every ward with new monitors."},{"form":"equipped","partOfSpeech":"adjective","example":"The kitchen is well equipped, with an oven and a large fridge.","pedagogicallyUseful":true,"altExample":"The gym is fully equipped with weights and running machines."}],"masteryPassages":[{"passageId":"u2_44_equipment_passage_1","contextId":"u2_44_equipment_gap_1","text":"Before the match, the coach checked that the team had everything it needed. The goals, nets and balls were all ready, but some of the training ____ was still in the van.","answer":"equipment"},{"passageId":"u2_44_equipment_passage_2","contextId":"u2_44_equipment_gap_2","text":"The laboratory buys new tools and machines every year. Without up-to-date ____, the students could not carry out the experiments.","answer":"equipment"}],"contextDependentParaphrases":[],"wrongParaphrases":["workers","payments","rules"],"misleadingDistractors":["rules for playing a game","a person who repairs machines","a room where tools are stored"]}]'::jsonb,'["equip","equipped"]'::jsonb,'["sports equipment","safety equipment","modern equipment"]'::jsonb,'live'),
('vocab_fixture','fixture','noun','a fitting, such as a light or a sink, that is permanently fixed in a building','[{"senseId":"fixture_1","meaning":"a fitting, such as a light or a sink, that is permanently fixed in a building","acceptedParaphrases":["fitting","permanent attachment"],"masteryContexts":[{"contextId":"u2_45_fixture_meaning","text":"The ceiling light is a fixture, so it stays when the family moves.","meaning":"something fitted permanently in a building","wrongMeanings":["something carried between rooms in a building","something borrowed for a short time in a building","something stored in a cupboard in a building"]},{"contextId":"u2_45_fixture_paraphrase","text":"The previous owners took their furniture but left every light and tap, because each one is a fixture.","meaning":"a fitting that stays in a building","wrongMeanings":["a decoration that is placed in a building","a person who works in a building","a machine that is moved around a building"]}],"situationDistractors":["The tenants packed their sofa and took it to the new flat.","The family hung a poster on the wall for the weekend.","The removal van carried the dining table down the stairs.","The family moved the sofa and the table to the new house.","The tenant brought a lamp and a small rug to the flat.","The teacher carried the books from the cupboard to her desk."],"gapDistractors":[{"contextId":"u2_45_fixture_gap_1","answer":"fixture","wrong":["sofa","suitcase","painting"]},{"contextId":"u2_45_fixture_gap_2","answer":"fixture","wrong":["sofa","suitcase","painting"]},{"contextId":"u2_45_fixture_gap_3","answer":"fixture","wrong":["sofa","suitcase","painting"]}],"spellingErrors":["fixtur","fixchure","fiksture","fixtre","fixure","fixtuer"],"wordFamilyForms":[{"form":"fixture","partOfSpeech":"noun","example":"The ceiling light is a fixture, so it stays in the flat.","pedagogicallyUseful":true},{"form":"fix","partOfSpeech":"verb","example":"The workers will fix the shelf to the wall tomorrow.","pedagogicallyUseful":true,"altExample":"Please fix the mirror to the wall with four screws."},{"form":"fixed","partOfSpeech":"adjective","example":"The table is fixed to the floor, so nobody can move it.","pedagogicallyUseful":true,"altExample":"The seats in the hall are fixed to the floor."}],"masteryPassages":[{"passageId":"u2_45_fixture_passage_1","contextId":"u2_45_fixture_gap_1","text":"When the family sold the flat, the buyers asked which items would stay. The kitchen sink was a ____, so it could not be taken away, but the table could.","answer":"fixture"},{"passageId":"u2_45_fixture_passage_2","contextId":"u2_45_fixture_gap_2","text":"The estate agent listed every light, radiator and tap in the house. Each ____ is attached to the building and is included in the sale price.","answer":"fixture"}],"contextDependentParaphrases":[],"wrongParaphrases":["visitor","tenant","invoice"],"misleadingDistractors":["a piece of furniture that can be carried away","a short-term repair","a decoration for a party"]}]'::jsonb,'["fix","fixed"]'::jsonb,'["bathroom fixture","light fixture","permanent fixture"]'::jsonb,'live'),
('vocab_removable','removable','adjective','able to be taken off or taken out','[{"senseId":"removable_1","meaning":"able to be taken off or taken out","acceptedParaphrases":["detachable","able to be taken off"],"masteryContexts":[{"contextId":"u2_46_removable_meaning","text":"The keyboard has removable keys for easy cleaning.","meaning":"able to be taken off","wrongMeanings":["able to be repaired quickly","able to be seen from outside","able to be bought separately"]},{"contextId":"u2_46_removable_paraphrase","text":"The phone has a removable battery, so you can replace it yourself.","meaning":"able to be taken out","wrongMeanings":["able to be charged very fast","able to be used underwater","able to be copied by others"]}],"situationDistractors":["The panel was glued tightly to the wall and would not move.","The screws held the shelf firmly in place.","The sticker was printed directly onto the plastic.","The phone has a battery that is sealed inside the body.","The cover was glued to the box and could not be opened.","The sticker would not come off, however hard she scratched it."],"gapDistractors":[{"contextId":"u2_46_removable_gap_1","answer":"removable","wrong":["permanent","fixed","tight"]},{"contextId":"u2_46_removable_gap_2","answer":"removable","wrong":["permanent","fixed","sewn"]},{"contextId":"u2_46_removable_gap_3","answer":"removable","wrong":["permanent","fixed","built-in"]}],"spellingErrors":["remuvable","removible","removabel","remmovable","removabal","remoovable"],"wordFamilyForms":[{"form":"removable","partOfSpeech":"adjective","example":"The phone has a removable cover, so you can change its colour.","pedagogicallyUseful":true},{"form":"remove","partOfSpeech":"verb","example":"Please remove your shoes before entering the house.","pedagogicallyUseful":true,"altExample":"Remove the lid before you heat the food."},{"form":"removal","partOfSpeech":"noun","example":"The removal of the old signs took a whole morning.","pedagogicallyUseful":true,"altExample":"Removal of the old carpet took two days."}],"masteryPassages":[{"passageId":"u2_46_removable_passage_1","contextId":"u2_46_removable_gap_1","text":"The new tablet has a thin cover that you can pull off with your fingers. Because the cover is ____, it is easy to clean and replace.","answer":"removable"},{"passageId":"u2_46_removable_passage_2","contextId":"u2_46_removable_gap_2","text":"Some old phones have a battery you can take out yourself. A ____ battery means that you do not have to buy a new phone when it stops working.","answer":"removable"}],"contextDependentParaphrases":[],"wrongParaphrases":["waterproof","fragile","portable"],"misleadingDistractors":["impossible to clean","permanently fixed","very expensive"]}]'::jsonb,'["remove","removal"]'::jsonb,'["removable cover","removable battery","removable lid"]'::jsonb,'live'),
('vocab_adjustable','adjustable','adjective','able to be changed or moved to suit different needs','[{"senseId":"adjustable_1","meaning":"able to be changed or moved to suit different needs","acceptedParaphrases":["able to be altered","changeable to fit"],"masteryContexts":[{"contextId":"u2_47_adjustable_meaning","text":"The bike has an adjustable seat for riders of different heights.","meaning":"able to be changed to fit","wrongMeanings":["able to be washed in water","able to be folded flat","able to be seen from far away"]},{"contextId":"u2_47_adjustable_paraphrase","text":"Use the adjustable strap to make the bag shorter or longer.","meaning":"able to be moved or changed","wrongMeanings":["able to be bought or sold","able to be lifted or carried","able to be wrapped or covered"]}],"situationDistractors":["The bolts held the seat in one fixed position.","The shoes came in only one size and could not be changed.","The shelf was fixed to the wall and could not be moved.","The chair is fixed to the floor and cannot be moved at all.","The bag has one short strap, and it cannot be changed.","The screen has a fixed angle, so only people in front can see it."],"gapDistractors":[{"contextId":"u2_47_adjustable_gap_1","answer":"adjustable","wrong":["fixed","permanent","immovable"]},{"contextId":"u2_47_adjustable_gap_2","answer":"adjustable","wrong":["fixed","permanent","durable"]},{"contextId":"u2_47_adjustable_gap_3","answer":"adjustable","wrong":["fixed","permanent","immovable"]}],"spellingErrors":["adjustible","adjustabel","ajustable","adjustble","adjusstable","adjustabal"],"wordFamilyForms":[{"form":"adjustable","partOfSpeech":"adjective","example":"The chair has an adjustable back for extra comfort.","pedagogicallyUseful":true},{"form":"adjust","partOfSpeech":"verb","example":"You can adjust the screen so that it faces you.","pedagogicallyUseful":true,"altExample":"Adjust the brightness if the screen is too dark."},{"form":"adjustment","partOfSpeech":"noun","example":"A small adjustment to the settings improved the sound.","pedagogicallyUseful":true,"altExample":"The driver made a small adjustment to the mirror."}],"masteryPassages":[{"passageId":"u2_47_adjustable_passage_1","contextId":"u2_47_adjustable_gap_1","text":"The desk chair suits tall and short students because the height can be changed. The ____ seat moves up and down with a small lever.","answer":"adjustable"},{"passageId":"u2_47_adjustable_passage_2","contextId":"u2_47_adjustable_gap_2","text":"Most backpacks have a strap that you can lengthen or shorten. An ____ strap makes the bag comfortable for people of different sizes.","answer":"adjustable"}],"contextDependentParaphrases":[],"wrongParaphrases":["able to be repaired","able to be hidden","able to be sold"],"misleadingDistractors":["very expensive","easy to break","fixed in one position"]}]'::jsonb,'["adjust","adjustment"]'::jsonb,'["adjustable seat","adjustable height","adjustable strap"]'::jsonb,'live'),
('vocab_affordable','affordable','adjective','not too expensive; cheap enough for most people to buy','[{"senseId":"affordable_1","meaning":"not too expensive; cheap enough for most people to buy","acceptedParaphrases":["reasonably priced","not too expensive"],"masteryContexts":[{"contextId":"u2_48_affordable_meaning","text":"In many big cities, affordable housing is hard to find.","meaning":"not too expensive for ordinary people","wrongMeanings":["built only for wealthy people","owned only by the government","designed only for young people"]},{"contextId":"u2_48_affordable_paraphrase","text":"Tablets are now cheap enough to be affordable for most schools.","meaning":"low enough in price to buy","wrongMeanings":["high enough in quality to use","light enough in weight to carry","small enough in size to hold"]}],"situationDistractors":["The jeweller sold a diamond necklace for thousands of pounds.","The shop gave away free samples to every customer.","The sports car was too costly for most families.","The new phone is extremely expensive, and only a few people can buy it.","The shop is always full of customers because it is open all night.","The flat is cheap, but it is damp and very small."],"gapDistractors":[{"contextId":"u2_48_affordable_gap_1","answer":"affordable","wrong":["luxurious","expensive","exclusive"]},{"contextId":"u2_48_affordable_gap_2","answer":"affordable","wrong":["luxury","expensive","exclusive"]},{"contextId":"u2_48_affordable_gap_3","answer":"affordable","wrong":["luxury","premium","exclusive"]}],"spellingErrors":["affordible","afordable","affordabel","affoardable","affordabal","affforable"],"wordFamilyForms":[{"form":"affordable","partOfSpeech":"adjective","example":"The company sells affordable laptops to students.","pedagogicallyUseful":true},{"form":"afford","partOfSpeech":"verb","example":"Few families can afford a holiday abroad every year.","pedagogicallyUseful":true,"altExample":"Many students cannot afford to live near the university."},{"form":"unaffordable","partOfSpeech":"adjective","example":"Rents in the capital have become unaffordable for most young people.","pedagogicallyUseful":true,"altExample":"The tickets were unaffordable for most families."}],"masteryPassages":[{"passageId":"u2_48_affordable_passage_1","contextId":"u2_48_affordable_gap_1","text":"Many families cannot buy a house in the city centre because prices are so high. Governments are therefore building ____ homes in the suburbs.","answer":"affordable"},{"passageId":"u2_48_affordable_passage_2","contextId":"u2_48_affordable_gap_2","text":"Ten years ago, a tablet cost as much as a laptop. Today there are cheaper models, and they are ____ enough for most schools to buy in large numbers.","answer":"affordable"}],"contextDependentParaphrases":[],"wrongParaphrases":["extremely rare","poorly made","widely sold"],"misleadingDistractors":["extremely expensive","free of charge","impossible to buy"]}]'::jsonb,'["afford","unaffordable"]'::jsonb,'["affordable housing","affordable price","reasonably affordable"]'::jsonb,'live'),
('vocab_external','external','adjective','outside something, or coming from outside it','[{"senseId":"external_1","meaning":"outside something, or coming from outside it","acceptedParaphrases":["outer","on the outside"],"masteryContexts":[{"contextId":"u2_49_external_meaning","text":"The external examiner visited the school to mark the speaking tests.","meaning":"from outside the organisation","wrongMeanings":["from inside the organisation","from a rival organisation","from a former member"]},{"contextId":"u2_49_external_paraphrase","text":"Connect an external hard drive to save extra files.","meaning":"separate from and outside the main device","wrongMeanings":["built into and inside the main device","faster than the main device","older than the main device"]}],"situationDistractors":["The pipes were hidden inside the walls of the building.","The teacher marked the tests herself.","The staff solved the problem without help from anyone else.","The data is stored inside the computer, on a drive built into the case.","The speaker is part of the television, so nothing needs to be plugged in.","Every teacher in the school helped to mark the exam papers."],"gapDistractors":[{"contextId":"u2_49_external_gap_1","answer":"external","wrong":["inner","central","hidden"]},{"contextId":"u2_49_external_gap_2","answer":"external","wrong":["internal","school-based","in-house"]},{"contextId":"u2_49_external_gap_3","answer":"external","wrong":["internal","central","built-in"]}],"spellingErrors":["externel","exturnal","extenal","extrenal","eksternal","externall"],"masteryPassages":[{"passageId":"u2_49_external_passage_1","contextId":"u2_49_external_gap_1","text":"The school’s own teachers marked the written papers. A visitor from another school, an ____ examiner, then checked a sample of the results.","answer":"external"},{"passageId":"u2_49_external_passage_2","contextId":"u2_49_external_gap_2","text":"My laptop is almost full, so I saved my photographs on a small ____ drive. I can now plug it in whenever I need more space.","answer":"external"}],"contextDependentParaphrases":[],"wrongParaphrases":["inner","central","hidden"],"misleadingDistractors":["inside the building","very old","hidden underground"]}]'::jsonb,'[]'::jsonb,'["external drive","external examiner","external speakers"]'::jsonb,'live'),
('vocab_concentrate','concentrate','verb','to give all your attention to one thing','[{"senseId":"concentrate_1","meaning":"to give all your attention to one thing","acceptedParaphrases":["focus","pay full attention"],"masteryContexts":[{"contextId":"u2_50_concentrate_meaning","text":"I cannot concentrate with the television on.","meaning":"give full attention to one thing","wrongMeanings":["stop thinking about anything","do several things at once","think about the past"]},{"contextId":"u2_50_concentrate_paraphrase","text":"You will make fewer mistakes if you concentrate on the task in front of you.","meaning":"give your full attention to","wrongMeanings":["write a plan for","ask for help with","hurry to finish"]}],"situationDistractors":["He checked his phone every minute during the lesson.","She chatted to her friend while the teacher spoke.","The student looked out of the window and daydreamed.","The students shouted and laughed in the corridor between lessons.","The teacher switched off the lights and left the room quickly.","He tried to do three things at once and finished none of them."],"gapDistractors":[{"contextId":"u2_50_concentrate_gap_1","answer":"concentrate","wrong":["rely","insist","depend"]},{"contextId":"u2_50_concentrate_gap_2","answer":"concentrate","wrong":["rely","insist","comment"]},{"contextId":"u2_50_concentrate_gap_3","answer":"concentrate","wrong":["rely","insist","depend"]}],"spellingErrors":["concentrat","consentrate","concentate","concentrait","concetrate","consentrait"],"wordFamilyForms":[{"form":"concentrate","partOfSpeech":"verb","example":"It is hard to concentrate when the room is noisy.","pedagogicallyUseful":true},{"form":"concentration","partOfSpeech":"noun","example":"Exams need a lot of concentration.","pedagogicallyUseful":true,"altExample":"Playing chess requires a great deal of concentration."},{"form":"concentrated","partOfSpeech":"adjective","example":"She made a concentrated effort to finish the essay.","pedagogicallyUseful":true,"altExample":"After a concentrated week of revision, she felt ready."}],"masteryPassages":[{"passageId":"u2_50_concentrate_passage_1","contextId":"u2_50_concentrate_gap_1","text":"Marta cannot revise at home because her brother plays loud music. In the library, it is quiet, and she is able to ____ for hours.","answer":"concentrate"},{"passageId":"u2_50_concentrate_passage_2","contextId":"u2_50_concentrate_gap_2","text":"The teacher asked the students to switch off their phones. “You will learn more if you ____ on the lesson and ignore everything else,” she said.","answer":"concentrate"}],"contextDependentParaphrases":[],"wrongParaphrases":["relax","wander","rest"],"misleadingDistractors":["become very tired","speak very quietly","forget something quickly"]}]'::jsonb,'["concentration","concentrated"]'::jsonb,'["concentrate hard","concentrate fully","cannot concentrate"]'::jsonb,'live')
